// Transforme chaque article du flux CERT-FR en un format commun aux 3 sources
const items = $input.all().filter(i => i.json.link || i.json.error);
if (items[0]?.json.error) return [{ json: { source: 'CERT-FR', erreur: String(items[0].json.error.message ?? items[0].json.error) } }];

return items.map(({ json: a }) => ({
  json: {
    source: 'CERT-FR',
    id: a.link,
    titre: a.title,
    lien: a.link,
    date: a.isoDate,
    detail: a.contentSnippet ?? '',
  },
}));

// Catalogue CISA KEV : vulnérabilités dont l'exploitation est CONFIRMÉE
const data = $input.first().json;
if (data.error) return [{ json: { source: 'KEV', erreur: String(data.error.message ?? data.error) } }];

return (data.vulnerabilities ?? []).map(v => ({
  json: {
    source: 'KEV',
    id: 'KEV:' + v.cveID, // préfixe : une CVE déjà vue côté NVD doit ré-alerter si elle devient exploitée
    cve: v.cveID,
    titre: `${v.cveID} — ${v.vendorProject} ${v.product}`,
    lien: `https://nvd.nist.gov/vuln/detail/${v.cveID}`,
    date: v.dateAdded,
    detail: v.shortDescription,
    ransomware: v.knownRansomwareCampaignUse === 'Known',
  },
}));

// NVD : CVE publiées récemment avec une sévérité CRITIQUE
const data = $input.first().json;
if (data.error) return [{ json: { source: 'NVD', erreur: String(data.error.message ?? data.error) } }];

// Score CVSS v3 en priorité : c'est celui que NVD utilise pour le filtre CRITICAL
function score(metrics = {}) {
  for (const k of ['cvssMetricV31', 'cvssMetricV30', 'cvssMetricV40']) {
    const s = metrics[k]?.[0]?.cvssData?.baseScore;
    if (s !== undefined) return s;
  }
  return null;
}

return (data.vulnerabilities ?? []).map(({ cve }) => ({
  json: {
    source: 'NVD',
    id: cve.id,
    cve: cve.id,
    titre: cve.id,
    score: score(cve.metrics),
    lien: `https://nvd.nist.gov/vuln/detail/${cve.id}`,
    date: cve.published + 'Z', // NVD donne l'heure UTC sans le préciser
    detail: cve.descriptions?.find(d => d.lang === 'en')?.value ?? '',
  },
}));

// Ne garde que ce qui est récent ET jamais envoyé.
// La mémoire des éléments déjà vus est conservée entre deux exécutions
// AUTOMATIQUES (pas lors des tests manuels, qui renvoient donc tout).
const JOUR = 24 * 3600 * 1000;
const FENETRE = 7 * JOUR;   // tolère un PC éteint jusqu'à 7 jours
const OUBLI = 30 * JOUR;    // au-delà, on purge la mémoire

const memoire = $getWorkflowStaticData('global');
memoire.vus ??= {};
const maintenant = Date.now();

const erreurs = [];
const nouveaux = [];
for (const { json: a } of $input.all()) {
  if (a.erreur) { erreurs.push(a); continue; }
  if (!a.id) continue; // élément vide (source sans résultat)
  const age = maintenant - new Date(a.date).getTime();
  if (!(age <= FENETRE)) continue;
  if (memoire.vus[a.id]) continue;
  memoire.vus[a.id] = maintenant;
  nouveaux.push(a);
}

for (const [id, t] of Object.entries(memoire.vus)) {
  if (maintenant - t > OUBLI) delete memoire.vus[id];
}

if (nouveaux.length === 0 && erreurs.length === 0) return []; // rien à dire : pas de message
return [{ json: { nouveaux, erreurs } }];

// Construit le(s) message(s) Telegram en HTML (limite Telegram : 4096 caractères)
const { nouveaux, erreurs } = $input.first().json;

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const court = (s, n = 220) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

const kev = nouveaux.filter(a => a.source === 'KEV');
const certfr = nouveaux.filter(a => a.source === 'CERT-FR');
// Une CVE présente dans KEV et NVD n'apparaît qu'une fois, dans KEV (plus grave)
const cveKev = new Set(kev.map(a => a.cve));
const nvd = nouveaux
  .filter(a => a.source === 'NVD' && !cveKev.has(a.cve))
  .sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

const lignes = [];
const heure = $now.setZone('Europe/Paris').toFormat("dd/MM/yyyy 'à' HH'h'mm");
lignes.push(`🛡️ <b>Veille cyber</b> — ${heure}`);

function section(titre, liste, ligne) {
  if (!liste.length) return;
  lignes.push('', `<b>${titre} (${liste.length})</b>`);
  for (const a of liste) lignes.push(ligne(a));
}

section('🔴 Exploitées activement — CISA KEV', kev, a =>
  `• <a href="${esc(a.lien)}">${esc(a.titre)}</a>${a.ransomware ? ' 💀 <i>ransomware</i>' : ''}\n  ${esc(court(a.detail))}`);
section('🇫🇷 Alertes CERT-FR', certfr, a =>
  `• <a href="${esc(a.lien)}">${esc(a.titre)}</a>`);
section('🟠 CVE critiques — NVD', nvd, a =>
  `• <a href="${esc(a.lien)}">${esc(a.titre)}</a> <b>CVSS ${a.score ?? '?'}</b>\n  ${esc(court(a.detail, 160))}`);

for (const e of erreurs) lignes.push('', `⚠️ Source <b>${esc(e.source)}</b> indisponible : ${esc(court(e.erreur, 150))}`);

// Découpage en plusieurs messages si nécessaire, sans couper une ligne
const messages = [];
let courant = '';
for (const l of lignes) {
  if (courant.length + l.length + 1 > 4000) { messages.push(courant); courant = ''; }
  courant += (courant ? '\n' : '') + l;
}
if (courant) messages.push(courant);

return messages.map(texte => ({ json: { texte } }));

// Mise en forme Discord (Markdown, 2000 caractères max par message).
// Les erreurs internes (sources indisponibles) restent sur Telegram : elles ne concernent pas le salon.
const { nouveaux } = $input.first().json;
if (!nouveaux?.length) return [];

// Neutralise le Markdown Discord et les mentions (@everyone...) dans les textes venus de l'extérieur
const net = s => String(s ?? '').replace(/([\\*_~`|>\[\]()])/g, '\\$1').replace(/@/g, '@\u200b');
const court = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

const kev = nouveaux.filter(a => a.source === 'KEV');
const certfr = nouveaux.filter(a => a.source === 'CERT-FR');
const cveKev = new Set(kev.map(a => a.cve));
const nvd = nouveaux.filter(a => a.source === 'NVD' && !cveKev.has(a.cve)).sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

const L = [`## 🛡️ Veille cyber — ${$now.setZone('Europe/Paris').toFormat("dd/MM/yyyy 'à' HH'h'mm")}`];
const section = (titre, liste, ligne) => {
  if (!liste.length) return;
  L.push('', `**${titre} (${liste.length})**`);
  for (const a of liste) L.push(ligne(a));
};
section('🔴 Exploitées activement — CISA KEV', kev, a =>
  `- [${net(a.titre)}](<${a.lien}>)${a.ransomware ? ' 💀 *ransomware*' : ''}\n  ${net(court(a.detail, 200))}`);
section('🇫🇷 Alertes CERT-FR', certfr, a => `- [${net(a.titre)}](<${a.lien}>)`);
section('🟠 CVE critiques — NVD', nvd, a =>
  `- [${net(a.titre)}](<${a.lien}>) **CVSS ${a.score ?? '?'}**\n  ${net(court(a.detail, 150))}`);

// Découpage à 1900 caractères, sans couper une ligne
const messages = [];
let courant = '';
for (const l of L) {
  if (courant.length + l.length + 1 > 1900) { messages.push(courant); courant = ''; }
  courant += (courant ? '\n' : '') + l;
}
if (courant) messages.push(courant);
return messages.map(texte => ({ json: { texte } }));

// Si Discord a refusé la publication, on le signale sur Telegram (la veille y est déjà partie)
const e = $input.all().find(i => i.json.error)?.json.error;
if (!e) return [];
return [{ json: { texte: `⚠️ Veille : publication Discord échouée (${String(e.message ?? e).slice(0, 150).replace(/[<>&]/g, '')})` } }];
